(function(root,factory){const api=factory(root.KanjiReadAbilities||(typeof require==='function'?require('./reading-abilities.js'):null),root.KanjiElementCharacters||(typeof require==='function'?require('./element-characters.js'):null),root.KanjiFishCharacters||(typeof require==='function'?require('./fish-characters.js'):null),root.KanjiTrialThemes||(typeof require==='function'?require('./special-trial-themes.js'):null));if(typeof module==='object'&&module.exports)module.exports=api;else root.KanjiMedals=api;})(typeof window!=='undefined'?window:globalThis,function(Read,Elements,Fish,Themes){
 'use strict';
 const attributes=['wood','fire','earth','metal','water'],keys=['friendsCpuDefeated','fiveAttributeWins','threeLinkWins','comebackWins','rubyAbilityVariety','fishTeamWins','elementTeamWins',...Themes.badges.filter(b=>b.tier===0).map(b=>b.key)];
 const definitions=[['friendship','交友の証','friendsCpuDefeated',[5,10,25],n=>`異なるフレンド${n}人のCPUに勝利`],['five-elements','五行の使い手','fiveAttributeWins',[10,30,100],n=>`五属性それぞれの文字を編成して各${n}勝`],['three-link','三字の連携','threeLinkWins',[1,10,30],n=>`自分3体がそれぞれ相手を1体以上落として${n}勝`],['companion','相棒の証','highestCharacterWins',[100,300,1000],n=>`同じ所持文字を使って${n}勝`],['comeback','逆転の証','comebackWins',[1,10,30],n=>`自分1体・相手3体の状態から逆転して${n}勝`],['technique','技巧の証','rubyAbilityVariety',[5,10,Object.keys(Read.abilities).length],n=>`装備ルビの異なる${n}種類の能力を発動した対局で勝利`],['fish-team','魚拓の証','fishTeamWins',[10,30,100],n=>`魚偏の文字3体の編成で${n}勝`],['element-team','元素の使い手','elementTeamWins',[10,30,100],n=>`元素文字3体の編成で${n}勝`]];
 const baseBadges=definitions.flatMap(([kind,name,key,values,condition])=>values.map((value,tier)=>({id:kind+'-'+['bronze','silver','gold'][tier],kind,name:name+'・'+['銅','銀','金'][tier],key,value,tier,condition:condition(value)+'（貸出文字・リプレイは対象外）'})));
 const badges=[...baseBadges,...Themes.badges];
 const empty=()=>({attributeWins:Object.fromEntries(attributes.map(a=>[a,0])),friendCodes:[],friendWins:{},abilities:[],threeLinkWins:0,comebackWins:0,fishTeamWins:0,elementTeamWins:0,settledIds:[]});
 const valid=p=>!!p&&typeof p==='object'&&p.friendWins&&typeof p.friendWins==='object'&&!Array.isArray(p.friendWins)&&Object.keys(p.friendWins).length<=10000&&Object.entries(p.friendWins).every(([code,wins])=>/^[A-Z2-9]{8}$/.test(code)&&Number.isInteger(wins)&&wins>=0&&wins<=1e9)&&p.attributeWins&&attributes.every(a=>Number.isInteger(p.attributeWins[a])&&p.attributeWins[a]>=0&&p.attributeWins[a]<=1e9)&&['threeLinkWins','comebackWins','fishTeamWins','elementTeamWins'].every(k=>Number.isInteger(p[k])&&p[k]>=0&&p[k]<=1e9)&&[['friendCodes',10000,v=>/^[A-Z2-9]{8}$/.test(v)],['abilities',100,v=>typeof v==='string'&&!!Read.abilities[v]],['settledIds',10000,v=>typeof v==='string'&&/^[a-zA-Z0-9_-]{8,120}$/.test(v)]].every(([k,max,test])=>Array.isArray(p[k])&&p[k].length<=max&&new Set(p[k]).size===p[k].length&&p[k].every(test));
 const initialize=state=>state.medalProgress||(state.medalProgress=empty());
 function start(id,team,{eligible=true,friendCode=null}={}){return{id,eligible,friendCode,team:team.map(i=>({...i,equippedReadings:(i.equippedReadings||[]).slice()})),kills:team.map(()=>0),abilities:[],comeback:false};}
 function observe(run,own,other){if(run?.eligible&&run.team.length===3&&own===1&&other===3)run.comeback=true;}
 function activate(run,item,ability){if(!run?.eligible||!ability||!Read.abilities[ability.id]||!run.team.some(i=>i.instanceId===item.instanceId&&Read.resolveAll(i).some(a=>a.id===ability.id)))return;if(!run.abilities.includes(ability.id))run.abilities.push(ability.id);}
 function sample(run,bodies){for(const b of bodies){const d=b.gameData;if(!d.isPlayer||d.isOut)continue;for(const [id,on]of Object.entries({backwater:d.rubyBackwater,resonance:d.rubyResonance,anchor:d.rubyState?.anchorMultiplier>1,charge:d.rubyState?.charge>0}))if(on)activate(run,d,Read.abilities[id]);}}
 function kill(run,instanceId){const n=run?.team.findIndex(i=>i.instanceId===instanceId);if(run?.eligible&&n>=0)run.kills[n]++;}
 function finish(state,run,winner){if(!run?.eligible)return false;const p=initialize(state);if(p.settledIds.includes(run.id))return false;p.settledIds.push(run.id);if(p.settledIds.length>10000)p.settledIds.shift();if(winner!==true)return false;
  const inc=k=>p[k]=Math.min(1e9,p[k]+1);for(const a of new Set(run.team.map(i=>i.attr)))if(attributes.includes(a))p.attributeWins[a]=Math.min(1e9,p.attributeWins[a]+1);
  if(run.friendCode&&/^[A-Z2-9]{8}$/.test(run.friendCode)){if(!p.friendCodes.includes(run.friendCode)&&p.friendCodes.length<10000)p.friendCodes.push(run.friendCode);if(p.friendCodes.includes(run.friendCode))p.friendWins[run.friendCode]=Math.min(1e9,(p.friendWins[run.friendCode]||0)+1);}
  if(run.team.length===3&&run.kills.every(n=>n>=1))inc('threeLinkWins');if(run.comeback)inc('comebackWins');
  if(run.team.length===3&&run.team.every(i=>Fish.has(i.char)))inc('fishTeamWins');if(run.team.length===3&&run.team.every(i=>Elements.has(i.char)))inc('elementTeamWins');
  for(const id of run.abilities)if(!p.abilities.includes(id)&&p.abilities.length<100)p.abilities.push(id);return true;
 }
 function progress(state){const themed=Themes.progress(state),p=state?.medalProgress;if(!valid(p))return{...Object.fromEntries(keys.map(k=>[k,0])),...themed};return{...themed,friendsCpuDefeated:p.friendCodes.length,fiveAttributeWins:Math.min(...attributes.map(a=>p.attributeWins[a])),threeLinkWins:p.threeLinkWins,comebackWins:p.comebackWins,rubyAbilityVariety:p.abilities.length,fishTeamWins:p.fishTeamWins,elementTeamWins:p.elementTeamWins};}
 return{attributes,keys,badges,empty,valid,initialize,start,observe,activate,sample,kill,finish,progress};
});
